{"expected_revision_id": "77ac1c5a-0123-42d3-9979-7b44d1a35339", "source": "module TopModule (
    input  logic clk,
    input  logic L,
    input  logic q_in,
    input  logic r_in,
    output logic Q
);

    // 2:1 multiplexer: select r_in when L is asserted, otherwise q_in.
    logic D;
    assign D = L ? r_in : q_in;

    // Power-up state so Q is defined from time 0 (no reset port in spec).
    initial Q = 1'b0;

    // D flip-flop capturing the multiplexer output.
    always @(posedge clk)
        Q <= D;

endmodule
"}
